## 5️⃣ `frontend/src/services/api.js` — Cliente API

```javascript
import axios from 'axios'

const api = axios.create({
  baseURL: '/api',
  headers: { 'Content-Type': 'application/json' }
})

// Interceptor JWT
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('fazluiz_token')
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

// Interceptor de errores
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('fazluiz_token')
      window.location.href = '/login'
    }
    return Promise.reject(error)
  }
)

// Auth
export const authAPI = {
  login: (data) => api.post('/auth/login', data),
  register: (data) => api.post('/auth/register', data),
  me: () => api.get('/auth/me'),
  refresh: () => api.post('/auth/refresh')
}

// CRM
export const crmAPI = {
  listClients: (params) => api.get('/crm/clients', { params }),
  getClient: (id) => api.get(`/crm/clients/${id}`),
  createClient: (data) => api.post('/crm/clients', data),
  updateClient: (id, data) => api.put(`/crm/clients/${id}`, data),
  addContact: (id, data) => api.post(`/crm/clients/${id}/contacts`, data),
  getFunnel: () => api.get('/crm/funnel')
}

// ERP
export const erpAPI = {
  listOrders: (params) => api.get('/erp/orders', { params }),
  createOrder: (data) => api.post('/erp/orders', data),
  updateOrder: (id, data) => api.put(`/erp/orders/${id}`, data),
  productionQueue: () => api.get('/erp/production-queue')
}

// STL
export const stlAPI = {
  analyze: (file) => {
    const formData = new FormData()
    formData.append('file', file)
    return api.post('/stl/analyze', formData, {
      headers: { 'Content-Type': 'multipart/form-data' }
    })
  },
  getAnalysis: (id) => api.get(`/stl/analysis/${id}`),
  listAnalyses: () => api.get('/stl/analyses')
}

// Calculator
export const calcAPI = {
  calculate: (data) => api.post('/calculator/calculate', data),
  compare: (data) => api.post('/calculator/compare', data),
  simulate: (data) => api.post('/calculator/simulate', data)
}

// Invoice
export const invoiceAPI = {
  listInvoices: () => api.get('/invoice/invoices'),
  createInvoice: (data) => api.post('/invoice/invoices', data),
  generateInvoicePDF: (id) => api.post(`/invoice/invoices/${id}/pdf`),
  listQuotes: () => api.get('/invoice/quotes'),
  createQuote: (data) => api.post('/invoice/quotes', data),
  generateQuotePDF: (id) => api.post(`/invoice/quotes/${id}/pdf`)
}

// Dashboard
export const dashboardAPI = {
  full: () => api.get('/dashboard/full'),
  kpis: () => api.get('/dashboard/kpis'),
  revenueChart: () => api.get('/dashboard/revenue-chart'),
  ordersStatus: () => api.get('/dashboard/orders-status'),
  topClients: () => api.get('/dashboard/top-clients'),
  inventoryAlerts: () => api.get('/dashboard/inventory-alerts'),
  printers: () => api.get('/dashboard/printers'),
  profitability: () => api.get('/dashboard/profitability')
}

// Inventory
export const inventoryAPI = {
  listItems: (params) => api.get('/inventory/items', { params }),
  createItem: (data) => api.post('/inventory/items', data),
  updateItem: (id, data) => api.put(`/inventory/items/${id}`, data),
  addMovement: (data) => api.post('/inventory/movements', data),
  getAlerts: () => api.get('/inventory/alerts')
}

// AI
export const aiAPI = {
  generateEmail: (data) => api.post('/ai/generate-email', data),
  generateLinkedin: (data) => api.post('/ai/generate-linkedin', data),
  analyzeLead: (data) => api.post('/ai/analyze-lead', data),
  salesArguments: (data) => api.post('/ai/sales-arguments', data),
  listLeads: () => api.get('/ai/leads')
}

// Tiberion (IA central)
export const tiberionAPI = {
  chat: (message, context) => api.post('/tiberion/chat', { message, context }),
  ceoReport: () => api.get('/tiberion/ceo-report'),
  voiceCommand: (transcript) => api.post('/tiberion/voice', { transcript }),
  analyzeImage: (file) => {
    const formData = new FormData()
    formData.append('file', file)
    return api.post('/tiberion/vision', formData, {
      headers: { 'Content-Type': 'multipart/form-data' }
    })
  }
}

export default api
```

