## 7️⃣ `frontend/src/components/layout/Sidebar.jsx`

```jsx
import { NavLink, useNavigate } from 'react-router-dom'
import { useAuthStore } from '@/store/authStore'
import { 
  LayoutDashboard, Users, Package, Calculator, FileText, 
  BarChart3, Box, Bot, Printer, Calendar, Settings, 
  LogOut, Sparkles, Upload
} from 'lucide-react'
import { clsx } from 'clsx'

const menuItems = [
  { path: '/', icon: LayoutDashboard, label: 'Dashboard' },
  { path: '/crm', icon: Users, label: 'CRM' },
  { path: '/orders', icon: Package, label: 'Pedidos' },
  { path: '/calculator', icon: Calculator, label: 'Calculadora' },
  { path: '/invoices', icon: FileText, label: 'Facturación' },
  { path: '/inventory', icon: Box, label: 'Inventario' },
  { path: '/stl', icon: Upload, label: 'Analizar STL' },
  { path: '/workshop', icon: Printer, label: 'Gemelo Digital' },
  { path: '/calendar', icon: Calendar, label: 'Agenda' },
  { path: '/analytics', icon: BarChart3, label: 'Analytics' },
  { path: '/tiberion', icon: Sparkles, label: 'Tiberion AI' },
  { path: '/settings', icon: Settings, label: 'Configuración' },
]

export function Sidebar() {
  const navigate = useNavigate()
  const { logout, user } = useAuthStore()

  const handleLogout = () => {
    logout()
    navigate('/login')
  }

  return (
    <aside className="w-64 h-screen glass-panel fixed left-0 top-0 flex flex-col z-40">
      {/* Logo */}
      <div className="p-6 border-b border-faz-glass-border">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-faz-gradient flex items-center justify-center shadow-glow-blue">
            <Box className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-display font-bold text-lg text-gradient">FazLuiz 3D</h1>
            <p className="text-xs text-faz-titanium">SaaS Platform</p>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto scrollbar-glass p-4 space-y-1">
        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) => clsx(
              'flex items-center gap-3 px-4 py-3 rounded-xl transition-all group',
              isActive 
                ? 'bg-faz-gradient text-white shadow-glow-blue/30' 
                : 'text-faz-titanium hover:bg-faz-glass hover:text-white'
            )}
          >
            <item.icon className="w-5 h-5" />
            <span className="font-medium text-sm">{item.label}</span>
          </NavLink>
        ))}
      </nav>

      {/* User */}
      <div className="p-4 border-t border-faz-glass-border">
        <div className="glass-card p-3 mb-3">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-faz-gradient flex items-center justify-center font-bold">
              {user?.name?.charAt(0) || 'T'}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">{user?.name || 'Thiago Luiz'}</p>
              <p className="text-xs text-faz-titanium truncate">{user?.email}</p>
            </div>
          </div>
        </div>
        <button 
          onClick={handleLogout}
          className="w-full flex items-center gap-3 px-4 py-2 rounded-xl text-faz-titanium hover:text-white hover:bg-faz-glass transition-all"
        >
          <LogOut className="w-4 h-4" />
          <span className="text-sm">Cerrar sesión</span>
        </button>
      </div>
    </aside>
  )
}
