## 8️⃣ `frontend/src/pages/Dashboard.jsx` — Dashboard principal

```jsx
import { useEffect, useState } from 'react'
import { dashboardAPI } from '@/services/api'
import { 
  TrendingUp, Package, Clock, DollarSign, Users, 
  AlertTriangle, Activity
} from 'lucide-react'
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, PieChart, Pie, Cell, BarChart, Bar
} from 'recharts'
import { motion } from 'framer-motion'

const COLORS = ['#2D7FF9', '#22D3EE', '#8B5CF6', '#F59E0B', '#10B981']

export function Dashboard() {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadDashboard()
  }, [])

  const loadDashboard = async () => {
    try {
      const { data: result } = await dashboardAPI.full()
      setData(result)
    } catch (error) {
      console.error(error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) return <LoadingSkeleton />
  if (!data) return null

  const kpis = [
    { label: 'Ingresos (30d)', value: `R$ ${data.kpis.monthly_revenue.toLocaleString()}`, icon: DollarSign, color: 'from-blue-500 to-cyan-500' },
    { label: 'Pedidos Activos', value: data.kpis.active_orders, icon: Package, color: 'from-purple-500 to-pink-500' },
    { label: 'Horas Impresas', value: data.kpis.printing_hours, icon: Clock, color: 'from-amber-500 to-orange-500' },
    { label: 'Clientes Activos', value: data.kpis.active_clients, icon: Users, color: 'from-emerald-500 to-teal-500' },
  ]

  return (
    <div className="p-8 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-display font-bold">Buenos días, Thiago 👋</h1>
          <p className="text-faz-titanium mt-1">Aquí está el estado de tu negocio hoy</p>
        </div>
        <button className="btn-primary flex items-center gap-2">
          <Sparkles className="w-4 h-4" />
          Preguntar a Tiberion
        </button>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {kpis.map((kpi, idx) => (
          <motion.div
            key={kpi.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.1 }}
            className="stat-card"
          >
            <div className="flex items-start justify-between">
              <div>
                <p className="text-sm text-faz-titanium">{kpi.label}</p>
                <p className="text-2xl font-bold mt-2">{kpi.value}</p>
              </div>
              <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${kpi.color} flex items-center justify-center shadow-lg`}>
                <kpi.icon className="w-6 h-6 text-white" />
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Revenue Chart */}
        <div className="lg:col-span-2 glass-panel p-6">
          <h3 className="font-display font-semibold text-lg mb-4">Ingresos últimos 6 meses</h3>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data.revenue_chart}>
              <defs>
                <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#2D7FF9" stopOpacity={0.8}/>
                  <stop offset="95%" stopColor="#22D3EE" stopOpacity={0.2}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
              <XAxis dataKey="month" stroke="#64748B" />
              <YAxis stroke="#64748B" />
              <Tooltip 
                contentStyle={{ 
                  background: 'rgba(15, 23, 42, 0.95)', 
                  border: '1px solid rgba(255,255,255,0.1)',
                  borderRadius: '12px'
                }}
              />
              <Line 
                type="monotone" 
                dataKey="revenue" 
                stroke="#2D7FF9" 
                strokeWidth={3}
                fill="url(#colorRevenue)"
                dot={{ fill: '#22D3EE', r: 5 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* Orders by Status */}
        <div className="glass-panel p-6">
          <h3 className="font-display font-semibold text-lg mb-4">Pedidos por estado</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={data.orders_status}
                dataKey="count"
                nameKey="status"
                cx="50%"
                cy="50%"
                outerRadius={80}
                label
              >
                {data.orders_status.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
