      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Upload & Viewer */}
        <div className="glass-panel p-6 space-y-4">
          <div 
            onClick={() => fileInputRef.current?.click()}
            className="border-2 border-dashed border-faz-glass-border rounded-xl p-12 text-center cursor-pointer hover:border-faz-blue transition-all"
          >
            <Upload className="w-12 h-12 mx-auto text-faz-titanium mb-4" />
            <p className="font-medium">
              {file ? file.name : 'Haz clic para subir un archivo STL'}
            </p>
            <p className="text-sm text-faz-titanium mt-2">Máximo 100MB</p>
            <input
              ref={fileInputRef}
              type="file"
              accept=".stl"
              onChange={handleFileChange}
              className="hidden"
            />
          </div>

          {previewUrl && (
            <div className="h-80 bg-faz-dark/50 rounded-xl overflow-hidden border border-faz-glass-border">
              <Canvas camera={{ position: [0, 0, 5], fov: 50 }}>
                <ambientLight intensity={0.5} />
                <directionalLight position={[10, 10, 5]} intensity={1} />
                <Center>
                  <STLModel url={previewUrl} />
                </Center>
                <OrbitControls enableZoom enablePan enableRotate />
                <gridHelper args={[10, 10, '#2D7FF9', '#1E293B']} />
              </Canvas>
            </div>
          )}

          <button 
            onClick={handleAnalyze}
            disabled={!file || loading}
            className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? 'Analizando...' : '🔍 Analizar STL'}
          </button>
        </div>

        {/* Results */}
        <div className="space-y-4">
          {analysis ? (
            <>
              {/* Metrics */}
              <div className="grid grid-cols-2 gap-4">
                <MetricCard 
                  icon={Box} 
                  label="Volumen" 
                  value={`${analysis.volume_cm3} cm³`}
                  color="blue"
                />
                <MetricCard 
                  icon={DollarSign} 
                  label="Peso estimado" 
                  value={`${analysis.estimated_weight_grams} g`}
                  color="cyan"
                />
                <MetricCard 
                  icon={Clock} 
                  label="Tiempo impresión" 
                  value={`${analysis.estimated_time_hours} h`}
                  color="purple"
                />
                <MetricCard 
                  icon={Box} 
                  label="Triángulos" 
                  value={analysis.triangles.toLocaleString()}
                  color="amber"
                />
              </div>

              {/* Bounding Box */}
              <div className="glass-panel p-6">
                <h3 className="font-semibold mb-3">Dimensiones (mm)</h3>
                <div className="grid grid-cols-3 gap-3">
                  <div className="glass-card p-3 text-center">
                    <p className="text-xs text-faz-titanium">X</p>
                    <p className="font-bold text-lg">{analysis.bounding_box_mm.x.toFixed(1)}</p>
                  </div>
                  <div className="glass-card p-3 text-center">
                    <p className="text-xs text-faz-titanium">Y</p>
                    <p className="font-bold text-lg">{analysis.bounding_box_mm.y.toFixed(1)}</p>
                  </div>
                  <div className="glass-card p-3 text-center">
                    <p className="text-xs text-faz-titanium">Z</p>
                    <p className="font-bold text-lg">{analysis.bounding_box_mm.z.toFixed(1)}</p>
                  </div>
