## 🔟 `frontend/src/pages/GemeloDigital.jsx` — Gemelo Digital 3D del Taller

```jsx
import { useEffect, useState, useRef } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { OrbitControls, Text, Box as DreiBox, Html } from '@react-three/drei'
import { dashboardAPI } from '@/services/api'
import { Printer as PrinterIcon, AlertCircle, Activity } from 'lucide-react'
import * as THREE from 'three'

function PrinterModel({ position, printer, onClick }) {
  const meshRef = useRef()
  const [hovered, setHovered] = useState(false)

  const statusColors = {
    idle: '#64748B',
    printing: '#10B981',
    maintenance: '#F59E0B',
    offline: '#EF4444'
  }

  const color = statusColors[printer.status] || '#64748B'

  useFrame((state) => {
    if (meshRef.current && printer.status === 'printing') {
      // Animación de "impresión" - layers
      meshRef.current.children[1].scale.y = 0.5 + Math.sin(state.clock.elapsedTime * 2) * 0.1
    }
  })

  return (
    <group 
      position={position} 
      onClick={onClick}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      {/* Base */}
      <mesh ref={meshRef} castShadow receiveShadow>
        <DreiBox args={[2, 0.3, 2]}>
          <meshStandardMaterial color="#1E293B" metalness={0.5} roughness={0.3} />
        </DreiBox>
        {/* Cuerpo impresora */}
        <DreiBox args={[1.8, 1.8, 1.8]} position={[0, 1, 0]}>
          <meshStandardMaterial 
            color={color} 
            metalness={0.7} 
            roughness={0.2}
            emissive={color}
            emissiveIntensity={hovered ? 0.5 : 0.2}
          />
        </DreiBox>
      </mesh>

      {/* Etiqueta */}
      <Text
        position={[0, 2.5, 0]}
        fontSize={0.2}
        color="white"
        anchorX="center"
        anchorY="middle"
      >
        {printer.name}
      </Text>

      {/* Estado */}
      <Html position={[0, 3, 0]} center>
        <div className={`px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap ${
          printer.status === 'printing' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' :
          printer.status === 'idle' ? 'bg-slate-500/20 text-slate-400 border border-slate-500/30' :
          printer.status === 'maintenance' ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' :
          'bg-red-500/20 text-red-400 border border-red-500/30'
        }`}>
          {printer.status === 'printing' && '🖨️ Imprimiendo'}
          {printer.status === 'idle' && '⏸️ Idle'}
          {printer.status === 'maintenance' && '🔧 Mantenimiento'}
          {printer.status === 'offline' && '⚫ Offline'}
        </div>
      </Html>

      {/* Glow si está imprimiendo */}
      {printer.status === 'printing' && (
        <pointLight position={[0, 1, 0]} color={color} intensity={2} distance={5} />
      )}
    </group>
  )
}

function Floor() {
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.15, 0]} receiveShadow>
      <planeGeometry args={[50, 50]} />
      <meshStandardMaterial 
        color="#0F172A" 
        metalness={0.8} 
        roughness={0.4}
      />
    </mesh>
  )
}

function Grid() {
  return <gridHelper args={[50, 50, '#2D7FF9', '#1E293B']} position={[0, -0.14, 0]} />
}

export function GemeloDigital() {
  const [printers, setPrinters] = useState([])
  const [selected, setSelected] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadPrinters()
    const interval = setInterval(loadPrinters, 5000) // Actualiza cada 5s
    return () => clearInterval(interval)
  }, [])

  const loadPrinters = async () => {
    try {
      const { data } = await dashboardAPI.printers()
      setPrinters(data)
    } catch (error) {
      console.error(error)
    } finally {
      setLoading(false)
    }
  }

  // Posiciones en grid
  const positions = printers.map((_, idx) => {
    const row = Math.floor(idx / 3)
    const col = idx % 3
    return [col * 4 - 4, 0, row * 4 - 4]
  })

  const stats = {
    total: printers.length,
    printing: printers.filter(p => p.status === 'printing').length,
    idle: printers.filter(p => p.status === 'idle').length,
    maintenance: printers.filter(p => p.status === 'maintenance').length,
    offline: printers.filter(p => p.status === 'offline').length,
  }

  return (
    <div className="p-8 space-y-6">
      <div>
        <h1 className="text-3xl font-display font-bold">Gemelo Digital del Taller</h1>
        <p className="text-faz-titanium mt-1">Visualización 3D en tiempo real de todas las impresoras</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <StatCard label="Total" value={stats.total} color="blue" />
        <StatCard label="Imprimiendo" value={stats.printing} color="emerald" />
        <StatCard label="Idle" value={stats.idle} color="slate" />
        <StatCard label="Mantenimiento" value={stats.maintenance} color="amber" />
        <StatCard label="Offline" value={stats.offline} color="red" />
      </div>

      {/* 3D Scene */}
      <div className="glass-panel p-6">
        <div className="h-[600px] rounded-xl overflow-hidden bg-faz-dark/50 border border-faz-glass-border">
          <Canvas
            shadows
            camera={{ position: [15, 12, 15], fov: 50 }}
            gl={{ antialias: true }}
          >
            <ambientLight intensity={0.4} />
            <directionalLight
              position={[10, 15, 10]}
              intensity={1}
              castShadow
              shadow-mapSize={[2048, 2048]}
            />
            <pointLight position={[-10, 10, -10]} intensity={0.5} color="#22D3EE" />

            <Floor />
            <Grid />

            {printers.map((printer, idx) => (
              <PrinterModel
                key={printer.id}
                position={positions[idx]}
                printer={printer}
                onClick={() => setSelected(printer)}
              />
            ))}

            <OrbitControls 
              enableZoom 
              enablePan 
              maxPolarAngle={Math.PI / 2.2}
              minDistance={5}
              maxDistance={30}
            />

            <fog attach="fog" args={['#0F172A', 20, 50]} />
          </Canvas>
        </div>
      </div>

      {/* Selected Printer Details */}
      {selected && (
        <div className="glass-panel p-6 animate-layer-print">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h3 className="text-xl font-bold">{selected.name}</h3>
              <p className="text-faz-titanium">{selected.model}</p>
            </div>
            <button 
              onClick={() => setSelected(null)}
              className="text-faz-titanium hover:text-white"
            >
              ✕
            </button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <InfoCard label="Estado" value={selected.status} />
            <InfoCard label="Horas totales" value={`${selected.total_hours || 0}h`} />
            <InfoCard label="Trabajo actual" value={selected.current_job || 'Ninguno'} />
            <InfoCard 
              label="Próximo mantenimiento" 
              value={selected.next_maintenance 
                ? new Date(selected.next_maintenance).toLocaleDateString()
                : 'No programado'
              }
            />
          </div>
        </div>
      )}
    </div>
  )
}

function StatCard({ label, value, color }) {
  const colors = {
    blue: 'from-blue-500 to-cyan-500',
    emerald: 'from-emerald-500 to-teal-500',
    slate: 'from-slate-500 to-slate-600',
    amber: 'from-amber-500 to-orange-500',
    red: 'from-red-500 to-rose-500'
  }
  return (
    <div className="glass-card p-4">
      <div className={`w-2 h-8 rounded-full bg-gradient-to-b ${colors[color]} mb-2`}></div>
      <p className="text-2xl font-bold">{value}</p>
      <p className="text-xs text-faz-titanium">{label}</p>
    </div>
  )
}

function InfoCard({ label, value }) {
  return (
    <div className="glass-card p-3">
      <p className="text-xs text-faz-titanium">{label}</p>
      <p className="font-medium mt-1 capitalize">{value}</p>
    </div>
