import { useState, useRef, useEffect } from 'react'
import { tiberionAPI } from '@/services/api'
import { Send, Mic, MicOff, Sparkles, Bot, User, Brain } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import toast from 'react-hot-toast'

export function Tiberion() {
  const [messages, setMessages] = useState([
    {
      role: 'assistant',
      content: 'Buenos días, Thiago. Soy Tiberion, tu copiloto de negocio. ¿En qué puedo ayudarte hoy?',
      timestamp: new Date()
    }
  ])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [listening, setListening] = useState(false)
  const messagesEndRef = useRef(null)

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const sendMessage = async () => {
    if (!input.trim()) return

    const userMessage = { role: 'user', content: input, timestamp: new Date() }
    setMessages(prev => [...prev, userMessage])
    setInput('')
    setLoading(true)

    try {
      const { data } = await tiberionAPI.chat(input, { context: 'general' })
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: data.response,
        actions: data.actions,
        timestamp: new Date()
      }])
    } catch (error) {
      toast.error('Error al contactar con Tiberion')
    } finally {
      setLoading(false)
    }
  }

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      toast.error('Tu navegador no soporta reconocimiento de voz')
      return
    }

    if (listening) {
      setListening(false)
      return
    }

    const recognition = new window.webkitSpeechRecognition()
    recognition.lang = 'es-ES'
    recognition.continuous = false

    recognition.onstart = () => setListening(true)
    recognition.onend = () => setListening(false)
    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript
      setInput(transcript)
    }

    recognition.start()
  }

  const quickActions = [
    { label: '📊 Informe CEO', prompt: 'Dame el informe CEO de hoy' },
    { label: '💰 ¿Cuánto gané este mes?', prompt: '¿Cuánto he ganado este mes?' },
    { label: '🎯 Mejor cliente', prompt: '¿Cuál fue mi mejor cliente?' },
    { label: '🖨️ ¿Qué impresora termina antes?', prompt: '¿Qué impresora termina antes?' },
    { label: '📦 Stock bajo', prompt: '¿Qué materiales están bajos de stock?' },
    { label: '📈 Previsión', prompt: 'Haz una previsión de ingresos para el próximo mes' },
  ]

  return (
    <div className="h-screen flex flex-col p-8">
      {/* Header */}
      <div className="glass-panel p-6 mb-6">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 rounded-2xl bg-faz-gradient flex items-center justify-center shadow-glow-blue animate-pulse-slow">
            <Brain className="w-8 h-8 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-display font-bold text-gradient">Tiberion AI</h1>
            <p className="text-faz-titanium text-sm">Tu copiloto de negocio • Conectado a todos los módulos</p>
          </div>
          <div className="ml-auto flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
            <span className="text-xs text-emerald-400">Online</span>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-glass">
        {quickActions.map((action) => (
          <button
            key={action.label}
            onClick={() => setInput(action.prompt)}
            className="glass-card px-4 py-2 text-sm whitespace-nowrap hover:bg-faz-glass transition-all"
          >
            {action.label}
          </button>
        ))}
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto scrollbar-glass space-y-4 py-4">
        <AnimatePresence>
          {messages.map((msg, idx) => (
            <motion.div
              key={idx}
