"""Finance Agent — Gestión financiera"""
from datetime import datetime, timedelta
from typing import Dict, Optional
from app.models import Invoice, Order, Client
from app.extensions import db
from sqlalchemy import func

class FinanceAgent:
    def __init__(self, core):
        self.core = core

    def process(self, message: str, context: Optional[Dict]) -> Dict:
        msg_lower = message.lower()

        if 'mes' in msg_lower and ('gan' in msg_lower or 'ingres' in msg_lower):
            return self._monthly_revenue()
        elif 'beneficio' in msg_lower or 'margen' in msg_lower:
            return self._profitability()
        elif 'cliente' in msg_lower and 'rentable' in msg_lower:
            return self._most_profitable_client()
        elif 'predecir' in msg_lower or 'previsión' in msg_lower:
            return self._forecast()
        else:
            return self._general_finance(message)

    def _monthly_revenue(self) -> Dict:
        last_30 = datetime.utcnow() - timedelta(days=30)
        invoices = Invoice.query.filter(
            Invoice.status == 'paid',
            Invoice.issue_date >= last_30
        ).all()

        total = sum(i.total for i in invoices)
        count = len(invoices)
        avg = total / count if count > 0 else 0

        return {
            "content": f"""💰 Ingresos últimos 30 días:

• Total facturado: R$ {total:,.2f}
• Número de facturas: {count}
• Ticket medio: R$ {avg:,.2f}

Esto representa un {'buen' if total > 10000 else 'normal'} mes.""",
            "agent": "finance",
            "actions": []
        }

    def _profitability(self) -> Dict:
        # Calcular rentabilidad
        return {
            "content": "📊 Analizando rentabilidad...",
            "agent": "finance",
            "actions": []
        }

    def _most_profitable_client(self) -> Dict:
        top = Client.query.order_by(Client.total_spent.desc()).first()
        if top:
            return {
                "content": f"🏆 Tu cliente más rentable es {top.contact_name} de {top.company_name or 'empresa particular'}, con R$ {top.total_spent:,.2f} en compras totales.",
                "agent": "finance",
                "actions": []
            }
