"""Print Agent — Gestión de impresión 3D"""
from typing import Dict, Optional
from app.models import Printer, Order

class PrintAgent:
    def __init__(self, core):
        self.core = core

    def process(self, message: str, context: Optional[Dict]) -> Dict:
        msg_lower = message.lower()

        if 'termina' in msg_lower or 'antes' in msg_lower:
            return self._next_finish()
        elif 'impresora' in msg_lower and ('usar' in msg_lower or 'recomend' in msg_lower):
            return self._recommend_printer(context)
        elif 'estado' in msg_lower:
            return self._printers_status()
        else:
            return self.core._handle_core(message, context)

    def _next_finish(self) -> Dict:
        printing = Order.query.filter_by(status='printing').all()
        if not printing:
            return {
                "content": "No hay pedidos imprimiéndose ahora mismo.",
                "agent": "print",
                "actions": []
            }

        # El que tenga menos tiempo restante (estimado)
        next_one = min(printing, key=lambda o: o.estimated_hours or 999)
        return {
            "content": f"🖨️ La impresora que termina antes está trabajando en el pedido {next_one.order_number}, con {next_one.estimated_hours or '?'} horas estimadas.",
            "agent": "print",
            "actions": []
        }

    def _recommend_printer(self, context: Optional[Dict]) -> Dict:
        idle_printers = Printer.query.filter_by(status='idle').all()
        if idle_printers:
            names = ", ".join([p.name for p in idle_printers])
            return {
                "content": f"✅ Impresoras disponibles ahora: {names}",
                "agent": "print",
                "actions": []
            }
        return {
            "content": "Todas las impresoras están ocupadas. La que antes queda libre es...",
            "agent": "print",
            "actions": []
        }

    def _printers_status(self) -> Dict:
        printers = Printer.query.all()
        status_summary = {}
        for p in printers:
            status_summary[p.status] = status_summary.get(p.status, 0) + 1

        content = "🖨️ Estado de impresoras:\n\n"
        for status, count in status_summary.items():
            content += f"• {status.capitalize()}: {count}\n"

        return {"content": content, "agent": "print", "actions": []}
