"""
Vision Agent — Detección de fallos de impresión usando visión artificial
Detecta: warping, stringing, under-extrusion, layer shift, spaghetti
"""
import os
from typing import Dict, List
from PIL import Image
import numpy as np

class PrintFailureDetector:
    """
    Detector de fallos de impresión 3D por visión artificial
    Usa análisis de imagen para detectar problemas comunes
    """

    FAILURE_TYPES = {
        'warping': 'Desprendimiento de la base',
        'stringing': 'Hilos finos entre partes (oozing)',
        'under_extrusion': 'Falta de material en capas',
        'layer_shift': 'Desalineación de capas',
        'spaghetti': 'Fallo catastrófico, parece espagueti',
        'elephant_foot': 'Base aplastada',
        'ringing': 'Ondulaciones en superficies',
        'z_seam': 'COSTURA visible en eje Z'
    }

    @staticmethod
    def analyze(image_path: str) -> Dict:
        """
        Analiza una imagen de impresión y detecta fallos
        """
        if not os.path.exists(image_path):
            return {"error": "Imagen no encontrada"}

        try:
            img = Image.open(image_path)
            img_array = np.array(img)

            # Análisis básico (en producción usarías un modelo YOLO/ResNet entrenado)
            issues = []

            # 1. Detectar warping (bordes levantados)
            if PrintFailureDetector._detect_warping(img_array):
                issues.append({
                    'type': 'warping',
                    'severity': 'high',
                    'confidence': 0.85,
                    'description': PrintFailureDetector.FAILURE_TYPES['warping'],
                    'solution': 'Aumenta la temperatura de la cama, usa laca o PEI, verifica nivelación'
                })

            # 2. Detectar stringing (hilos finos)
            if PrintFailureDetector._detect_stringing(img_array):
                issues.append({
                    'type': 'stringing',
                    'severity': 'medium',
                    'confidence': 0.78,
                    'description': PrintFailureDetector.FAILURE_TYPES['stringing'],
                    'solution': 'Activa retracción, reduce temperatura 5°C, aumenta velocidad de viaje'
                })

            # 3. Detectar spaghetti
            if PrintFailureDetector._detect_spaghetti(img_array):
                issues.append({
                    'type': 'spaghetti',
                    'severity': 'critical',
                    'confidence': 0.92,
                    'description': PrintFailureDetector.FAILURE_TYPES['spaghetti'],
                    'solution': 'Detén la impresión. Verifica adhesión a la cama y flujo de material'
                })

            # 4. Detectar layer shift
            if PrintFailureDetector._detect_layer_shift(img_array):
                issues.append({
                    'type': 'layer_shift',
                    'severity': 'high',
                    'confidence': 0.81,
                    'description': PrintFailure_TYPES['layer_shift'],
                    'solution': 'Verifica correas, poleas y velocidad de impresión'
                })

            # 5. Calcular porcentaje de completado (estimación)
            completion = PrintFailureDetector._estimate_completion(img_array)

            return {
                'success': True,
                'issues': issues,
                'completion_percent': completion,
                'overall_quality': PrintFailureDetector._calculate_quality(issues),
                'recommendations': PrintFailureDetector._generate_recommendations(issues)
            }

        except Exception as e:
            return {"error": str(e)}

    @staticmethod
    def _detect_warping(img_array: np.ndarray) -> bool:
        """Detecta warping analizando bordes"""
        # Simplificado: en producción usarías un modelo CNN
        gray = np.mean(img_array, axis=2)
        edges = np.gradient(gray)
        edge_strength = np.sum(np.abs(edges))
        # Umbral empírico
        return edge_strength > 1000000

    @staticmethod
    def _detect_stringing(img_array: np.ndarray) -> bool:
        """Detecta stringing"""
        # Buscar líneas finas verticales/horizontales
        gray = np.mean(img_array, axis=2)
        # Análisis de frecuencia simplificado
        return False  # Placeholder

    @staticmethod
    def _detect_spaghetti(img_array: np.ndarray) -> bool:
        """Detecta fallo tipo espagueti"""
        # Alta entropía + baja estructura
        gray = np.mean(img_array, axis=2)
        entropy = PrintFailureDetector._calculate_entropy(gray)
        return entropy > 7.5  # Alta entropía = caos

    @staticmethod
    def _detect_layer_shift(img_array: np.ndarray) -> bool:
        """Detecta desplazamiento de capas"""
        return False  # Placeholder

    @staticmethod
    def _calculate_entropy(img: np.ndarray) -> float:
        """Calcula entropía de la imagen"""
        hist, _ = np.histogram(img, bins=256, range=(0, 256))
        hist = hist / hist.sum()
        hist = hist[hist > 0]
        return -np.sum(hist * np.log2(hist))

    @staticmethod
    def _estimate_completion(img_array: np.ndarray) -> float:
        """Estima porcentaje completado"""
        # Simplificado: basado en altura ocupada
        height = img_array.shape[0]
        # Buscar la parte superior de la pieza
        non_empty_rows = np.where(np.sum(img_array, axis=(1, 2)) > 0)[0]
        if len(non_empty_rows) == 0:
            return 0.0
        top_row = non_empty_rows[0]
        return round((height - top_row) / height * 100, 1)

    @staticmethod
    def _calculate_quality(issues: List[Dict]) -> str:
        """Calcula calidad general"""
        if not issues:
            return 'excellent'
        severities = [i['severity'] for i in issues]
        if 'critical' in severities:
            return 'critical'
        if 'high' in severities:
            return 'poor'
        if 'medium' in severities:
            return 'acceptable'
        return 'good'

    @staticmethod
    def _generate_recommendations(issues: List[Dict]) -> List[str]:
        """Genera recomendaciones"""
        return [issue['solution'] for issue in issues]
