import { useState, useRef } from 'react'
import { stlAPI } from '@/services/api'
import { Upload, Box, Clock, DollarSign, AlertTriangle, CheckCircle2 } from 'lucide-react'
import { Canvas } from '@react-three/fiber'
import { OrbitControls, STLLoader, Center } from '@react-three/drei'
import { useLoader } from '@react-three/fiber'
import toast from 'react-hot-toast'

function STLModel({ url }) {
  const geometry = useLoader(STLLoader, url)
  return (
    <mesh geometry={geometry}>
      <meshStandardMaterial 
        color="#2D7FF9" 
        metalness={0.3} 
        roughness={0.5}
        wireframe={false}
      />
    </mesh>
  )
}

export function STLAnalyzer() {
  const [file, setFile] = useState(null)
  const [previewUrl, setPreviewUrl] = useState(null)
  const [analysis, setAnalysis] = useState(null)
  const [loading, setLoading] = useState(false)
  const fileInputRef = useRef(null)

  const handleFileChange = (e) => {
    const selected = e.target.files[0]
    if (selected && selected.name.toLowerCase().endsWith('.stl')) {
      setFile(selected)
      setPreviewUrl(URL.createObjectURL(selected))
      setAnalysis(null)
    }
  }

  const handleAnalyze = async () => {
    if (!file) return
    setLoading(true)
    try {
      const { data } = await stlAPI.analyze(file)
      setAnalysis(data.result)
      toast.success('Análisis completado')
    } catch (error) {
      toast.error('Error al analizar STL')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="p-8 space-y-6">
      <div>
        <h1 className="text-3xl font-display font-bold">Analizador de STL</h1>
        <p className="text-faz-titanium mt-1">Sube un archivo STL para análisis técnico completo</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Upload & Viewer */}
        <div className="glass-panel p-6 space-y-4">
          <div 
            onClick={() => fileInputRef.current?.click()}
            className="border-2 border-dashed border-faz-glass-border rounded-xl p-12 text-center cursor-pointer hover:border-faz-blue transition-all"
          >
            <Upload className="w-12 h-12 mx-auto text-faz-titanium mb-4" />
            <p className="font-medium">
              {file ? file.name : 'Haz clic para subir un archivo STL'}
            </p>
            <p className="text-sm text-faz-titanium mt-2">Máximo 100MB</p>
            <input
              ref={fileInputRef}
              type="file"
              accept=".stl"
              onChange={handleFileChange}
              className="hidden"
            />
          </div>

          {previewUrl && (
            <div className="h-80 bg-faz-dark/50 rounded-xl overflow-hidden border border-faz-glass-border">
              <Canvas camera={{ position: [0, 0, 5], fov: 50 }}>
                <ambientLight intensity={0.5} />
                <directionalLight position={[10, 10, 5]} intensity={1} />
                <Center>
                  <STLModel url={previewUrl} />
                </Center>
                <OrbitControls enableZoom enablePan enableRotate />
                <gridHelper args={[10, 10, '#2D7FF9', '#1E293B']} />
              </Canvas>
            </div>
          )}

          <button 
            onClick={handleAnalyze}
            disabled={!file || loading}
            className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? 'Analizando...' : '🔍 Analizar STL'}
          </button>
        </div>

        {/* Results */}
        <div className="space-y-4">
          {analysis ? (
            <>
              {/* Metrics */}
              <div className="grid grid-cols-2 gap-4">
                <MetricCard 
                  icon={Box} 
                  label="Volumen" 
                  value={`${analysis.volume_cm3} cm³`}
                  color="blue"
                />
                <MetricCard 
                  icon={DollarSign} 
                  label="Peso estimado" 
                  value={`${analysis.estimated_weight_grams} g`}
                  color="cyan"
                />
                <MetricCard 
                  icon={Clock} 
                  label="Tiempo impresión" 
                  value={`${analysis.estimated_time_hours} h`}
                  color="purple"
                />
                <MetricCard 
                  icon={Box} 
                  label="Triángulos" 
                  value={analysis.triangles.toLocaleString()}
                  color="amber"
                />
              </div>

