## 1️⃣6️⃣ BACKEND — Rutas Tiberion y Visión

### `app/tiberion/routes.py`

```python
from flask import Blueprint, request, jsonify, current_app
from flask_jwt_extended import jwt_required
import os

tiberion_bp = Blueprint('tiberion', __name__)

@tiberion_bp.route('/chat', methods=['POST'])
@jwt_required()
def chat():
    data = request.get_json()
    message = data.get('message', '')
    context = data.get('context', {})

    from tiberion.core.brain import TiberionCore
    core = TiberionCore(current_app)
    response = core.process(message, context)

    return jsonify(response), 200

@tiberion_bp.route('/ceo-report', methods=['GET'])
@jwt_required()
def ceo_report():
    from tiberion.core.brain import TiberionCore
    core = TiberionCore(current_app)
    report = core.ceo_morning_report()
    return jsonify(report), 200

@tiberion_bp.route('/vision', methods=['POST'])
@jwt_required()
def vision():
    if 'file' not in request.files:
        return jsonify({"error": "No file"}), 400

    file = request.files['file']
    upload_folder = current_app.config['UPLOAD_FOLDER']
    vision_folder = os.path.join(upload_folder, 'vision')
    os.makedirs(vision_folder, exist_ok=True)

    filename = file.filename
    file_path = os.path.join(vision_folder, filename)
    file.save(file_path)

    from vision.detector import PrintFailureDetector
    result = PrintFailureDetector.analyze(file_path)

    return jsonify(result), 200
```

